-- spies, stubs and mocks on lib functions, lib variables, handle methods, module exports and tables.
local combat = require("game.combat")

describe("spies", function()
    it("spy.new records calls (ok)", function()
        local s = spy.new(function(x) return x * 2 end)
        assert.equals(6, s(3))
        assert.spy(s).was.called(1)
        assert.spy(s).was.called_with(3)
        assert.spy(s).was.returned_with(6)
        assert.spy(s).was_not.called_with(4)
    end)

    it("spy.on a lib function keeps it working (ok)", function()
        local s = spy.on(arena, "spawn")
        assert.equals(2, arena.spawn("orc", 2))
        assert.spy(s).was.called_with("orc", 2)
        expect(arena.spawn).to.have_been_called(1)
        assert.equals(1, arena.count())
    end)

    it("the lib function is back after the test (ok)", function()
        assert.is_false(spy.is_spy(arena.spawn))
        assert.equals(0, arena.count())
    end)

    it("stub a lib function (ok)", function()
        stub(arena, "spawn").returns(99)
        assert.equals(99, arena.spawn("orc", 1))
        assert.equals(0, arena.count())
        assert.stub(arena.spawn).was.called_with("orc", match.is_number())
    end)

    it("stub on_call_with (ok)", function()
        local s = stub(arena, "spawn")
        s.on_call_with("boss", match._).returns(7)
        s.returns(1)
        assert.equals(7, arena.spawn("boss", 3))
        assert.equals(1, arena.spawn("orc", 3))
    end)

    it("stub invokes (ok)", function()
        stub(arena, "spawn").invokes(function(kind, n) return #kind + n end)
        assert.equals(5, arena.spawn("orc", 2))
    end)

    it("stub.var replaces a lib variable (ok)", function()
        stub.var(arena, "gravity", 2.5)
        assert.equals(2.5, arena.gravity)
        arena.gravity = 4
        assert.equals(4, arena.gravity)
    end)

    it("the variable is back (ok)", function()
        assert.equals(9.5, arena.gravity)
    end)

    it("spy on a handle method (ok)", function()
        local u = arena.make(1)
        local s = spy.on(u, "move")
        assert.equals(3, u:move(2))
        assert.spy(s).was.called(1)
    end)

    it("stub a handle method for every handle (ok)", function()
        local a, b = arena.make(1), arena.make(2)
        stub(a, "move").returns(-1)
        assert.equals(-1, a:move(5))
        assert.equals(-1, b:move(5))
    end)

    it("handle methods are back (ok)", function()
        local u = arena.make(1)
        assert.equals(6, u:move(5))
    end)

    it("spy on a module export (ok)", function()
        local s = spy.on(combat, "damage")
        assert.equals(7, combat.damage(10, 3))
        assert.spy(s).was.called_with(10, 3)
    end)

    it("stub a module export used by the module (ok)", function()
        stub(combat, "sum").returns(-5)
        assert.equals(-5, combat.sum(10))
    end)

    it("the module export is back (ok)", function()
        assert.equals(55, combat.sum(10))
    end)

    it("mock a table (ok)", function()
        local t = { f = function() return 1 end, g = function() return 2 end, v = 3 }
        mock(t)
        assert.equals(1, t.f())
        assert.spy(t.f).was.called()
        assert.spy(t.g).was_not.called()
        mock.revert(t)
        assert.is_false(spy.is_spy(t.f))
        local m = mock({ f = function() return 1 end }, true)
        assert.is_nil(m.f())
    end)

    it("revert early (ok)", function()
        local s = spy.on(arena, "spawn")
        s:revert()
        assert.is_false(spy.is_spy(arena.spawn))
    end)

    it("called too often (fails)", function()
        local s = spy.new(function() end)
        s()
        s()
        assert.spy(s).was.called(1)
    end)

    it("called with other arguments (fails)", function()
        local s = spy.on(arena, "spawn")
        arena.spawn("orc", 1)
        assert.spy(s).was.called_with("elf", 1)
    end)

    it("expect have_been_called_with (fails)", function()
        local s = stub(arena, "spawn")
        arena.spawn("orc", 1)
        expect(s).to.have_been_called_with("orc", 2)
    end)
end)
